import axios from "axios";
import { Spinner } from "reactstrap";
import React, { Component } from "react";
import { Modal, ModalHeader, ModalBody } from "reactstrap";
import { connect } from "react-redux";
import { updateUsers } from "../../../actions/userAccessUserActions";
import PropTypes from "prop-types";
import { login, loadUser } from "../../../actions/authActions";
import { clearErrors } from "../../../actions/errorActions";
import store from "../../../store";
import {
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper
} from "@material-ui/core";

class UserAccessModal extends Component {
  state = {
    modal: false,
    chooseUserRowData: [],
    selectedUserRowData: [],
    tableLoaded: false,
    columnSelectedUsers: [
      { title: "ID", field: "id" },
      { title: "Name", field: "name" }
    ],
    columns: [
      { title: "ID", field: "id" },
      { title: "Name", field: "name" },
      { title: "Current Access", field: "currentAccess" }
    ]
  };
  componentDidMount() {
    this.retrieveFromDb();
  }
  toggle = () => {
    this.setState({
      modal: !this.state.modal
    });
  };
  retrieveFromDb = () => {
    this.setState(state => ({
      tableLoaded: false,
      chooseUserRowData: state.chooseUserRowData
    }));
    axios
      .get("/api/userList")
      .then(res => {
        var userRowData = res.data.map((x, index) => {
          return {
            id: x._id,
            name: x.name,
            currentAccess: x.userAccess.name,
            currentAccessId: x.userAccess._id
          };
        });

        var chooseUserRowData = userRowData.filter(x => {
          return x.currentAccessId != this.props.userAccessId;
        });

        var selectedUserRowData = userRowData.filter(x => {
          return x.currentAccessId == this.props.userAccessId;
        });

        this.setState(state => ({
          tableLoaded: true,
          chooseUserRowData,
          selectedUserRowData
        }));
      })
      .catch(err => console.log(err));
  };

  addUser = event => {
    var chooseUserRowData = this.state.chooseUserRowData;
    var selectedUserRowData = this.state.selectedUserRowData;
    chooseUserRowData = chooseUserRowData.filter((x, index) => {
      if (event.id == x.id) {
        selectedUserRowData.push(x);
      }
      return x.id != event.id;
    });
    this.setState({
      selectedUserRowData,
      chooseUserRowData
    });
    this.props.updateUsers(selectedUserRowData);
  };
  removeUser = event => {
    var chooseUserRowData = this.state.chooseUserRowData;
    var selectedUserRowData = this.state.selectedUserRowData;
    selectedUserRowData = selectedUserRowData.filter((x, index) => {
      if (event.id == x.id) {
        chooseUserRowData.push(x);
      }
      return x.id != event.id;
    });
    this.setState({
      selectedUserRowData,
      chooseUserRowData
    });
    this.props.updateUsers(selectedUserRowData);
  };

  render() {
    return (
      <div>
        <Button
          className="mt-2 mb-3"
          variant="contained"
          color="primary"
          onClick={this.toggle}
        >
          Assign Users
        </Button>
        <Modal size={"lg"} isOpen={this.state.modal} toggle={this.toggle}>
          <ModalHeader toggle={this.toggle}>Assign Users</ModalHeader>
          <ModalBody>
            {this.state.tableLoaded ? (
              <div>
                <h5 className="mt-2">Selected Users</h5>
                <TableContainer className="mb-2" component={Paper}>
                  <Table aria-label="simple table">
                    <TableHead>
                      <TableRow>
                        <TableCell>User IDs</TableCell>
                        <TableCell>Name</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {this.state.selectedUserRowData.map(row => (
                        <TableRow
                          key={row.id}
                          onClick={this.removeUser.bind(this, row)}
                        >
                          <TableCell component="th" scope="row">
                            {row.id}
                          </TableCell>
                          <TableCell>{row.name}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
                <h5>Choose Users</h5>
                <TableContainer component={Paper}>
                  <Table aria-label="simple table">
                    <TableHead>
                      <TableRow>
                        <TableCell>User IDs</TableCell>
                        <TableCell>Name</TableCell>
                        <TableCell>Current Access</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {this.state.chooseUserRowData.map(row => (
                        <TableRow
                          key={row.id}
                          onClick={this.addUser.bind(this, row)}
                        >
                          <TableCell component="th" scope="row">
                            {row.id}
                          </TableCell>
                          <TableCell>{row.name}</TableCell>
                          <TableCell>{row.currentAccess}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
                <div className="mb-2"> </div>
              </div>
            ) : (
              <div
                style={{
                  display: "flex",
                  justifyContent: "center"
                }}
              >
                <Spinner animation="border" />
              </div>
            )}
          </ModalBody>
        </Modal>
      </div>
    );
  }
}

const mapStateToProps = state => ({
  isAutheticated: state.auth.isAutheticated,
  error: state.error
});

export default connect(mapStateToProps, { updateUsers })(UserAccessModal);
//mapStateToProps gets state variables from elsewhere in the app.
//the stuff in the curly braces are methods brought in to modify state in other parts of the app
//all these things will be declared in the component props
